SourceCode.Declaration:
/// <summary>
/// initializes InfoFields records for existing DirTable records
/// </summary>
class AVAInfoFieldInitJob
{
}

Method.Source:
static void main(Args args)
{
    DirPartyTable       dirPartyTable;
    AVASalesInfoFields  infoFields, infoFieldsUpd;
    CustTable           custTable;
    smmBusRelTable      busRelTable;
    RecordInsertList    insList = new RecordInsertList(tableNum(AVASalesInfoFields));

    while select dirPartyTable
    notexists join infoFields where infoFields.Party == dirPartyTable.RecId
    {
        custTable   = CustTable::findByPartyRecId(dirPartyTable.RecId);
        busRelTable = smmBusRelTable::findByParty(dirPartyTable.RecId);
        if (custTable || busRelTable)
        {
            infoFieldsUpd.Party     = dirPartyTable.RecId;
            insList.add(infoFieldsUpd);
        }
    }
    insList.insertDatabase();
}
